#!/usr/bin/env python3
"""Install one generated compiler entry point; refuse unrelated project writes."""
import argparse
import json
from pathlib import Path
import shutil


MARKER = "// Generated by Sylphx unity-compile-scripts; no signing or native build."
ENTRY = "SylphxCompilePlayerScripts.Run"


def relative(value):
    path = Path(value)
    if path.is_absolute() or not path.parts or ".." in path.parts:
        raise ValueError("project/output paths must be workspace-relative without '..'")
    return path


def prepare(workspace, project, output, target):
    if target not in ("Android", "iOS"):
        raise ValueError("target must be Android or iOS")
    workspace = Path(workspace).resolve(strict=True)
    project = (workspace / relative(project)).resolve(strict=True)
    if not project.is_relative_to(workspace) or not (project / "Assets").is_dir() or not (project / "ProjectSettings/ProjectVersion.txt").is_file():
        raise ValueError("project must be a Unity project inside the workspace")
    output = relative(output)
    destination = (project / output).resolve()
    if not destination.is_relative_to(project):
        raise ValueError("output resolves outside the Unity project")
    editor = project / "Assets/Editor"
    editor.mkdir(exist_ok=True)
    if not editor.resolve().is_relative_to(project):
        raise ValueError("editor entry resolves outside the Unity project")
    entry = editor / "SylphxCompilePlayerScripts.cs"
    if entry.is_symlink():
        raise ValueError("refusing to overwrite a linked compiler entry")
    if entry.exists() and not entry.read_text().startswith(MARKER):
        raise ValueError("refusing to overwrite a consumer-owned compiler entry")
    source = Path(__file__).with_name("SylphxCompilePlayerScripts.cs")
    shutil.copyfile(source, entry)
    return {"project": str(project.relative_to(workspace)), "output": str(output), "method": ENTRY, "target": target}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--workspace", required=True)
    parser.add_argument("--project", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--target", required=True)
    args = parser.parse_args()
    try:
        print(json.dumps(prepare(args.workspace, args.project, args.output, args.target)))
    except (ValueError, OSError) as error:
        parser.exit(1, f"::error::{error}\n")
